const money=value=>`$${Number(value).toLocaleString('zh-TW')}`;
function renderMonthlySales(month){const report=monthlySalesReports[month];if(!report)return;document.querySelector('#monthOrders').textContent=report.orders.toLocaleString('zh-TW');document.querySelector('#monthCups').textContent=report.cups.toLocaleString('zh-TW');document.querySelector('#monthAdjustments').textContent=money(report.discount+report.refund);document.querySelector('#monthNetSales').textContent=money(report.net);document.querySelector('#monthGrowth').textContent=report.growth;document.querySelector('#monthlyEvidenceBadge').textContent=`${report.label}・${report.cups.toLocaleString('zh-TW')} 杯`;document.querySelector('#monthlySalesRows').innerHTML=report.rows.map(([branch,orders,cups,gross,discount,refund,net,best])=>`<tr><td>${branch}</td><td>${orders.toLocaleString('zh-TW')}</td><td>${cups.toLocaleString('zh-TW')}</td><td>${money(net)}</td><td>${money(Math.round(net/orders))}</td><td>${best}</td></tr>`).join('');document.querySelector('#monthTableOrders').textContent=report.orders.toLocaleString('zh-TW');document.querySelector('#monthTableCups').textContent=report.cups.toLocaleString('zh-TW');document.querySelector('#monthTableNet').textContent=money(report.net);document.querySelector('#monthTableAverage').textContent=money(Math.round(report.net/report.orders))}
function exportMonthlySales(){const month=document.querySelector('#salesMonth').value;const report=monthlySalesReports[month];const header=['月份','分店','完成訂單數','售出杯數','銷售原額','折扣','退款','實收營業額','網路訂單','現場平板訂單','櫃台訂單','當月熱銷'];const rows=report.rows.map(([branch,orders,cups,gross,discount,refund,net,best])=>{const online=Math.round(orders*.44),tablet=Math.round(orders*.37),counter=orders-online-tablet;return[report.label,branch,orders,cups,gross,discount,refund,net,online,tablet,counter,best]});rows.push([report.label,'十店合計',report.orders,report.cups,report.gross,report.discount,report.refund,report.net,'','','','']);const csv='\uFEFF'+[header,...rows].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`DrinkFlow_${month}_完整銷售.csv`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);if(typeof toast==='function')toast(`${report.label}完整銷售 CSV 已匯出`)}
document.querySelector('#salesMonth')?.addEventListener('change',event=>renderMonthlySales(event.target.value));document.querySelector('#exportMonthlySales')?.addEventListener('click',exportMonthlySales);renderMonthlySales(document.querySelector('#salesMonth')?.value||'2026-10');
